 'authenticated_execute',coalesce(has_function_privilege('authenticated',p.oid,'EXECUTE'),false),
 'service_execute',coalesce(has_function_privilege('service_role',p.oid,'EXECUTE'),false),
 'acl',p.proacl::text) order by expected.signature)
 from (values ('public.get_survey_allowance()','3b3b5e7c335a16a91c9f447b4ac8fd62b8f6e584273d9762c70c70a60be46ad5'),('public.enforce_survey_allowance()','2600d2e67866d1163846b11be2035a32dd0c6ea9e4116b36b1325308bbc7b368'),('public.protect_survey_address()','f2c82f9c423b45fa60fc191048b09c3645803847371cf03fbbf1a1ec391d3260'),('public.record_survey_purchase(text,text,uuid,integer,text,boolean)','5a054d2cae96b82d50cf390800fe4ac9aefaa23a71e961ae96e325eff461efed'),('public.revoke_survey_purchase(text,text)','09d97cbf0f492925affe2eca085eebdbaa12863269c6f7751be957678b77d433'),('public.claim_survey_notification(uuid,uuid,timestamptz)','835e5f5b72c24dea7c9d16f11ac7325c2127f9fe5003eb3321cad00a5debb624'),('public.finish_survey_notification(uuid,boolean)','b42ff776b1940ee8bd685a6eb547505f8c9b9b2d6f268998908bcfe4a92edc03'),('public.record_auth_registration()','80e273428f8ee6ec8a188445d74a579baeaddf7d73e26ccb6f05b45e278696bf'),('public.get_newsletter_preference()','fc4e8efe92594f8c04390286cc54debeca4ef170044419e920df7a6ef7e99362'),('public.set_newsletter_preference(boolean)','444919b10c66067288b457364d0fc49671fd9ca9c24fee315ba0029c92c16f32'),('public.recover_stale_registration_notifications()','fdebf598b2ac3fdfc3aa6b83b5d9c64a2df86bb032152f33720260cf09523c1b'),('public.claim_registration_notification()','a5a5e8223e299445928f58342eeb77f0069e840f786c1e18ed0f1a82dc54d072'),('public.finish_registration_notification(uuid,boolean)','fbdc1a1e12be5735936e934c9997ed823a61088424b3ecf0c66460deeede3668'),('public.finish_registration_notification(uuid,boolean,timestamptz)','cc58f7efefa6b569347ab55877667dbfd1f72fb80bd76d0f2ace2bf0cf547a28')) expected(signature,digest) left join pg_proc p on p.oid=to_regprocedure(expected.signature)),
 'new_tables',coalesce((select jsonb_agg(jsonb_build_object('table',c.relname,'rls',c.relrowsecurity,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl::text,
 'anon_any',has_table_privilege('anon',c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER'),
